import fs from 'fs/promises';
import path from 'path';

const DB_PATH = path.join(process.cwd(), 'app/notifications/db.json');

export async function getNotificationPreference(): Promise<boolean> {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8');
    return JSON.parse(data).notificationsEnabled;
  } catch (error) {
    // Default to false if file doesn't exist
    return false;
  }
}

export async function toggleNotificationPreferenceDB(): Promise<boolean> {
  const current = await getNotificationPreference();
  const updated = !current;
  await fs.writeFile(DB_PATH, JSON.stringify({ notificationsEnabled: updated }));
  return updated;
}

'use server';

import { revalidatePath } from 'next/cache';
import { toggleNotificationPreferenceDB } from './db';

export async function toggleNotifications() {
  await toggleNotificationPreferenceDB();
  revalidatePath('/notifications');
}

import { getNotificationPreference } from './db';
import { toggleNotifications } from './actions';

export default async function NotificationsPage() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <div className="p-8 font-sans">
      <h1 className="text-2xl font-bold mb-4">Notification Settings</h1>
      <div className="flex items-center gap-4 p-4 border rounded-lg bg-gray-50 dark:bg-gray-900">
        <div className="flex-1">
          <h2 className="font-semibold">Push Notifications</h2>
          <p className="text-sm text-gray-500">
            Receive updates about your account activity
          </p>
        </div>

        <form action={toggleNotifications}>
          <button
            type="submit"
            className={`px-4 py-2 rounded-full text-sm font-medium transition-colors ${
              notificationsEnabled
                ? 'bg-green-500 text-white hover:bg-green-600'
                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
            }`}
          >
            {notificationsEnabled ? 'On' : 'Off'}
          </button>
        </form>
      </div>
      <p className="mt-4 text-sm text-gray-500">
        Current status: <strong>{notificationsEnabled ? 'Enabled' : 'Disabled'}</strong>
      </p>
    </div>
  );
}

